/**
 * MealForward T1-F: LOCAL, non-transferrable proof of the *registered*
 * original Issuer EOA key via EIP-191 personal_sign.
 *
 * It is NOT SIWE, not a server session, not recipient enrollment, not an
 * issuer permission delegation, not an EIP-712 FundingQuote, not consent for
 * issuing/settlement, and NEVER authorizes a blockchain transaction.
 *
 * Challenge must be generated by the browser with crypto.getRandomValues;
 * verify it locally with pinned ethers.verifyMessage on the same device.
 * Because the nonce is NOT server-issued/stored, never accept this proof
 * as authorization for a backend Issue endpoint (replay is possible).
 */
export const ISSUER_ORIGIN='https://mealforward-t1d-funding-laodao.onrender.com';
export const ISSUER_ADDRESS='0x9747d93d9f8c2e1202b4d922a4916fcf634aa2b3';
export const ISSUER_ESCROW='0xcf0c8827c8610eeff1ecbd9719e559d805fafe58';
export const ISSUER_CHAIN=10143;
export const ISSUER_CHAIN_HEX='0x279f';
export const CHALLENGE_LIFETIME=300;

const NONCE=/^0x[0-9a-f]{64}$/;
const ECDSA=/^0x[0-9a-f]{130}$/i;
const same=(a,b)=>typeof a==='string'&&typeof b==='string'&&a.toLowerCase()===b.toLowerCase();
const assert=(v,why)=>{if(!v)throw Error(why)};
const safeTime=n=>Number.isSafeInteger(n)&&n>0&&n<9999999999;

export function buildIssuerControlChallenge({
 origin=ISSUER_ORIGIN,address,nonce,issuedAt
}={}){
 assert(origin===ISSUER_ORIGIN,'T1F_FOREIGN_ORIGIN_NOT_AUTHORIZED');
 assert(same(address,ISSUER_ADDRESS),'T1F_NOT_ORIGINAL_ISSUER_EOA');
 assert(typeof nonce==='string'&&NONCE.test(nonce)&&!/^0x0{64}$/.test(nonce),
  'T1F_BROWSER_CRYPTO_NONCE_REQUIRED');
 assert(safeTime(issuedAt),'T1F_ISSUER_TIMESTAMP_INVALID');
 const expiresAt=issuedAt+CHALLENGE_LIFETIME;
 const text=[
  'MealForward T1-F Issuer Wallet Control Proof ONLY',
  'This message is NOT a transaction or a voucher authorization.',
  'It is NOT a FundingQuote, Approve, Fund, Issue or Settle permit.',
  'Network: Monad Testnet (10143)',
  'Origin: '+ISSUER_ORIGIN,
  'StoreEscrow: '+ISSUER_ESCROW,
  'Registered Issuer: '+ISSUER_ADDRESS,
  'Nonce: '+nonce,
  'Issued At (Unix): '+issuedAt,
  'Expires At (Unix): '+expiresAt,
  'No signature bytes are sent to or saved by a backend.'
 ].join('\n');
 return Object.freeze({
  text,origin,issuer:ISSUER_ADDRESS,chainId:ISSUER_CHAIN,
  nonce,issuedAt,expiresAt,
  scope:'LOCAL_BROWSER_EIP191_KEY_CONTROL_ONLY',
  validForBackendIssue:false,
  fundsAuthorization:false
 });
}
export function verifyIssuerControlChallenge({
 challenge,signature,selectedAccount,chainId,origin,now,recover
}={}){
 assert(challenge?.scope==='LOCAL_BROWSER_EIP191_KEY_CONTROL_ONLY',
  'T1F_WRONG_CHALLENGE_SCOPE');
 assert(origin===ISSUER_ORIGIN&&challenge.origin===ISSUER_ORIGIN,
  'T1F_ORIGIN_CHANGED_DURING_SIGNATURE');
 assert(same(selectedAccount,ISSUER_ADDRESS)&&same(challenge.issuer,ISSUER_ADDRESS),
  'T1F_ISSUER_ACCOUNT_CHANGED');
 assert((typeof chainId==='string'||typeof chainId==='number')&&
  BigInt(chainId)===BigInt(ISSUER_CHAIN),'T1F_CHAIN_CHANGED');
 assert(safeTime(now)&&
  now>=challenge.issuedAt&&now<challenge.expiresAt&&
  challenge.expiresAt===challenge.issuedAt+CHALLENGE_LIFETIME,
  'T1F_PROOF_EXPIRED_OR_CLOCK_CHANGED');
 const expected=buildIssuerControlChallenge({
  origin,address:selectedAccount,nonce:challenge.nonce,
  issuedAt:challenge.issuedAt
 });
 assert(expected.text===challenge.text,'T1F_PROOF_TEXT_MODIFIED');
 assert(typeof signature==='string'&&ECDSA.test(signature),
  'T1F_INVALID_EIP191_SIGNATURE');
 assert(typeof recover==='function','T1F_EIP191_RECOVERY_REQUIRED');
 const signer=recover(challenge.text,signature);
 assert(same(signer,ISSUER_ADDRESS),'T1F_RECOVERED_SIGNER_NOT_ISSUER');
 // Do not expose raw signature, nonce, challenge or reusable auth capability.
 return Object.freeze({
  status:'LOCAL_ISSUER_EOA_EIP191_PROOF_PASS',
  verifiedAddress:ISSUER_ADDRESS,
  chainId:ISSUER_CHAIN,
  origin:ISSUER_ORIGIN,
  onchainIssuerControlDemonstratedBySignature:true,
  backedByServerChallenge:false,
  validForServerAuthorization:false,
  recipientConsentVerified:false,
  originalVoucherIssued:false,
  transactionsSent:0
 });
}
